BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path=public,extensions;
SELECT plan(13);
INSERT INTO public.tenants(id,name,slug) VALUES ('91000000-0000-0000-0000-000000000001','Storage test','storage-test');
INSERT INTO auth.users(id,email) VALUES ('9a000000-0000-0000-0000-000000000001','storage-test@example.invalid');
UPDATE public.profiles SET tenant_id='91000000-0000-0000-0000-000000000001',is_active=true WHERE id='9a000000-0000-0000-0000-000000000001';
INSERT INTO public.user_roles(user_id,role) VALUES ('9a000000-0000-0000-0000-000000000001','admin');
CREATE TEMP TABLE storage_test_ids(candidate_id uuid, upload_id uuid,resume_id uuid,job_id uuid,lease uuid);
GRANT ALL ON storage_test_ids TO authenticated,service_role;
SELECT ok(NOT has_function_privilege('authenticated','public.claim_resume_storage_jobs(uuid,integer)','EXECUTE'),'clients cannot claim privileged jobs');
SELECT ok(NOT has_function_privilege('authenticated','public.record_validated_resume_upload(uuid,text)','EXECUTE'),'clients cannot bless unvalidated upload content');
SELECT ok(NOT has_table_privilege('authenticated','private.resume_storage_jobs','SELECT'),'clients cannot read storage job paths');
SET LOCAL ROLE authenticated;
SET LOCAL "request.jwt.claim.role"='authenticated';
SET LOCAL "request.jwt.claim.sub"='9a000000-0000-0000-0000-000000000001';
INSERT INTO storage_test_ids(candidate_id) SELECT candidate_id FROM public.create_candidate_graph('{"first_name":"Storage","last_name":"Test"}',_resume => '{"file_name":"old.txt","mime_type":"text/plain","is_primary":true,"extracted_text":"Old facts"}');
UPDATE storage_test_ids SET upload_id=(SELECT upload_id FROM public.issue_resume_upload('new.pdf','application/pdf',3));
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT lives_ok($q$ SELECT public.record_validated_resume_upload((SELECT upload_id FROM storage_test_ids), repeat('a',64)) $q$,'trusted validator can record content digest');
SET LOCAL ROLE authenticated;
UPDATE storage_test_ids SET resume_id=(SELECT resume_id FROM public.attach_candidate_resume_from_upload((SELECT candidate_id FROM storage_test_ids),(SELECT upload_id FROM storage_test_ids),'New facts'));
SELECT is((SELECT file_name FROM public.resumes WHERE candidate_id=(SELECT candidate_id FROM storage_test_ids) AND is_primary),'old.txt','old original remains current while storage is pending');
SELECT is((SELECT storage_status FROM public.resumes WHERE id=(SELECT resume_id FROM storage_test_ids)),'pending','replacement starts pending');
RESET ROLE;
SELECT is((SELECT count(*) FROM private.resume_storage_jobs WHERE upload_id=(SELECT upload_id FROM storage_test_ids)),1::bigint,'job committed with metadata');
SET LOCAL ROLE service_role;
UPDATE storage_test_ids t SET job_id=j.id,lease=j.lease FROM public.claim_resume_storage_jobs((SELECT upload_id FROM storage_test_ids),1) j;
SELECT is((SELECT count(*) FROM public.claim_resume_storage_jobs((SELECT upload_id FROM storage_test_ids),1)),0::bigint,'active lease prevents duplicate workers');
SELECT public.retry_resume_storage_job((SELECT job_id FROM storage_test_ids),(SELECT lease FROM storage_test_ids));
SELECT is((SELECT count(*) FROM private.resume_storage_jobs WHERE id=(SELECT job_id FROM storage_test_ids)),1::bigint,'failure retains durable retry');
UPDATE private.resume_storage_jobs SET available_at=now() WHERE id=(SELECT job_id FROM storage_test_ids);
UPDATE storage_test_ids t SET lease=j.lease FROM public.claim_resume_storage_jobs((SELECT upload_id FROM storage_test_ids),1) j;
SELECT public.complete_resume_storage_job((SELECT job_id FROM storage_test_ids),(SELECT lease FROM storage_test_ids));
SELECT is((SELECT file_name FROM public.resumes WHERE candidate_id=(SELECT candidate_id FROM storage_test_ids) AND is_primary),'new.pdf','successful file transfer promotes replacement');
SELECT is((SELECT storage_status FROM public.resumes WHERE id=(SELECT resume_id FROM storage_test_ids)),'ready','replacement marked ready');
SELECT is((SELECT count(*) FROM private.resume_storage_jobs WHERE kind='delete-staging' AND candidate_id=(SELECT candidate_id FROM storage_test_ids)),1::bigint,'staging cleanup is also durable');
DELETE FROM public.candidates WHERE id=(SELECT candidate_id FROM storage_test_ids);
SELECT is((SELECT count(*) FROM private.resume_storage_jobs WHERE kind='delete' AND candidate_id=(SELECT candidate_id FROM storage_test_ids)),1::bigint,'candidate cascade enqueues file cleanup');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
